<input key={"v.flow.sel.t#1|" + String(v.flow.sel.t ?? "")} defaultValue={v.flow.sel.t} onBlur={v.flow.sel.set} style={{ border: "2px solid #14123a", borderRadius: "10px", padding: "8px 10px", font: "600 14px 'Instrument Sans'" } as any} />
