{(v.theme.cards || []).map((c: any, c_n: number) => (<Fragment key={c_n}><button onClick={c.go} style={{ textAlign: "left", border: `3px solid ${c.bd}`, boxShadow: `${c.sh}`, borderRadius: "18px", background: `${c.c}`, padding: "14px 16px", cursor: "pointer", display: "flex", gap: "12px", alignItems: "center", fontFamily: "inherit" } as any}><span style={{ fontSize: "40px" } as any}>{c.ic}</span><span style={{ font: "800 18px/1.2 'Familjen Grotesk',sans-serif", color: "#14123a" } as any}>{c.t}</span></button></Fragment>))}
